css:
.cat-appheader{display:flex;align-items:center;gap:18px;height:46px;padding:0 16px;border-radius:var(--cat-size-radius-md);background:var(--cat-semantic-chip-a);border:1px solid rgba(255,255,255,.5);box-shadow:inset 0 1px 0 rgba(255,255,255,.6);backdrop-filter:blur(var(--cat-blur-chip));-webkit-backdrop-filter:blur(var(--cat-blur-chip));font-family:var(--cat-font-family-ui)}
.cat-appheader .brand{font-weight:700;font-size:var(--cat-font-size-base)}
.cat-appheader nav{display:flex;gap:2px}
.cat-appheader nav a{padding:6px 10px;border-radius:var(--cat-size-radius-sm);font-size:var(--cat-font-size-base);color:var(--cat-color-ink-mid);cursor:pointer;text-decoration:none;transition:all var(--cat-motion-fast)}
.cat-appheader nav a:hover{color:var(--cat-color-ink-hi);background:rgba(255,255,255,.45)}
.cat-appheader nav a.is-active{color:var(--cat-color-ink-hi);font-weight:600}
.cat-appheader .spacer{flex:1}
